16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.time.temporal.ChronoUnit;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "address_line1")
44	    private String addressLine1;
45	
46	    @Column(name = "address_line2")
47	    private String addressLine2;
48	
49	    @Column(name = "city")
50	    @NotEmpty
51	    private String city;
52	
53	    @Column(name = "telephone")
54	    @NotEmpty
55	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: a '+' followed by 8 to 15 digits")
56	    private String telephone;
57	
58	    @Column(name = "email")
59	    private String email;
60	
61	    @Column(name = "registration_date")
62	    private LocalDate registrationDate;
63	
64	    @Column(name = "birth_date")
65	    private LocalDate birthDate;
66	
67	    @Column(name = "customer_code")
68	    private String customerCode;
69	
70	    @Column(name = "household_id")
71	    private String householdId;
72	
73	    @Column(name = "namesake_count")
74	    private Integer namesakeCount;
75	
76	    @Column(name = "membership_number")
77	    private String membershipNumber;
78	
79	    @Column(name = "bulk_signup_warning")
80	    private Boolean bulkSignupWarning;
81	
82	    @Column(name = "household_size")
83	    private Integer householdSize;
84	
85	    @Column(name = "postcode")
86	    private String postcode;
87	
88	    @Column(name = "possible_duplicate_of")
89	    private Integer possibleDuplicateOf;
90	
91	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
92	    private Set<Pet> pets;
93	
94	    public String getAddress() {
95	        return this.address;
96	    }
97	
98	    public void setAddress(String address) {
99	        this.address = address;
100	    }
101	
102	    /**
103	     * The first line of this owner's structured postal address, or {@code null} when the owner was
104	     * created with only the flat {@link #getAddress() address}. Preferred over the flat address when
105	     * present; see {@link #getAddress()} for the composed form.
106	     */
107	    public String getAddressLine1() {
108	        return this.addressLine1;
109	    }
110	
111	    public void setAddressLine1(String addressLine1) {
112	        this.addressLine1 = addressLine1;
113	    }
114	
115	    /**
116	     * The optional second line of this owner's structured postal address, or {@code null} when none
117	     * was supplied. When present it is appended to {@link #getAddressLine1() addressLine1} in the
118	     * composed {@link #getAddress() address}.
119	     */
120	    public String getAddressLine2() {
121	        return this.addressLine2;
122	    }
123	
124	    public void setAddressLine2(String addressLine2) {
125	        this.addressLine2 = addressLine2;
126	    }
127	
128	    public String getCity() {
129	        return this.city;
130	    }
131	
132	    public void setCity(String city) {
133	        this.city = city;
134	    }
135	
136	    public String getTelephone() {
137	        return this.telephone;
138	    }
139	
140	    public void setTelephone(String telephone) {
141	        this.telephone = telephone;
142	    }
143	
144	    /**
145	     * Return this owner's stored E.164 {@link #getTelephone() telephone} formatted for human display
146	     * as the calling code, a space, then the national digits grouped in threes, e.g.
147	     * {@code "+61 412 345 678"}. See {@link TelephoneFormatter}.
148	     */
149	    @Transient
150	    public String getTelephoneDisplay() {
151	        return TelephoneFormatter.toDisplay(this.telephone);
152	    }
153	
154	    public String getEmail() {
155	        return this.email;
156	    }
157	
158	    public void setEmail(String email) {
159	        this.email = email;
160	    }
161	
162	    public LocalDate getRegistrationDate() {
163	        return this.registrationDate;
164	    }
165	
166	    public void setRegistrationDate(LocalDate registrationDate) {
167	        this.registrationDate = registrationDate;
168	    }
169	
170	    public LocalDate getBirthDate() {
171	        return this.birthDate;
172	    }
173	
174	    public void setBirthDate(LocalDate birthDate) {
175	        this.birthDate = birthDate;
176	    }
177	
178	    public String getCustomerCode() {
179	        return this.customerCode;
180	    }
181	
182	    public void setCustomerCode(String customerCode) {
183	        this.customerCode = customerCode;
184	    }
185	
186	    public String getHouseholdId() {
187	        return this.householdId;
188	    }
189	
190	    public void setHouseholdId(String householdId) {
191	        this.householdId = householdId;
192	    }
193	
194	    public Integer getNamesakeCount() {
195	        return this.namesakeCount;
196	    }
197	
198	    public void setNamesakeCount(Integer namesakeCount) {
199	        this.namesakeCount = namesakeCount;
200	    }
201	
202	    public String getMembershipNumber() {
203	        return this.membershipNumber;
204	    }
205	
206	    public void setMembershipNumber(String membershipNumber) {
207	        this.membershipNumber = membershipNumber;
208	    }
209	
210	    /**
211	     * Whether this owner was created after more than 80 owners had already been registered on the
212	     * same day, flagging an unusually high-volume ("bulk") signup. Captured once at creation.
213	     */
214	    public Boolean getBulkSignupWarning() {
215	        return this.bulkSignupWarning;
216	    }
217	
218	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
219	        this.bulkSignupWarning = bulkSignupWarning;
220	    }
221	
222	    /**
223	     * The number of owners in this owner's household (owners sharing the same {@code householdId},
224	     * counting this owner) captured once at creation.
225	     */
226	    public Integer getHouseholdSize() {
227	        return this.householdSize;
228	    }
229	
230	    public void setHouseholdSize(Integer householdSize) {
231	        this.householdSize = householdSize;
232	    }
233	
234	    /**
235	     * This owner's 4-digit postcode, or {@code null} when none was supplied. When present it is
236	     * validated against the owner's city region at creation (see {@code PostcodeValidator}).
237	     */
238	    public String getPostcode() {
239	        return this.postcode;
240	    }
241	
242	    public void setPostcode(String postcode) {
243	        this.postcode = postcode;
244	    }
245	
246	    /**
247	     * The id of an existing owner this owner was flagged as a possible (soft) duplicate of at
248	     * creation, or {@code null} when none. Because owners sharing a last name and postcode now form
249	     * the same household — rejected as a household duplicate unless declared via {@code sharesHousehold},
250	     * and a declared member is not a suspected duplicate — this is not populated at creation.
251	     * Captured once at creation.
252	     */
253	    public Integer getPossibleDuplicateOf() {
254	        return this.possibleDuplicateOf;
255	    }
256	
257	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
258	        this.possibleDuplicateOf = possibleDuplicateOf;
259	    }
260	
261	    /**
262	     * Whether this owner was flagged as a possible (soft) duplicate of an existing owner at creation,
263	     * i.e. whether {@link #getPossibleDuplicateOf()} is set.
264	     */
265	    @Transient
266	    public Boolean getPossibleDuplicate() {
267	        return this.possibleDuplicateOf != null;
268	    }
269	
270	    /**
271	     * Return this owner's name formatted for display as {@code "LastName, FirstName"}.
272	     */
273	    @Transient
274	    public String getDisplayName() {
275	        return this.getLastName() + ", " + this.getFirstName();
276	    }
277	
278	    /**
279	     * Return this owner's initials as the upper-cased first letters of the first and last
280	     * name, dot-separated with a trailing dot, e.g. {@code "J.S."}.
281	     */
282	    @Transient
283	    public String getInitials() {
284	        return initial(this.getFirstName()) + initial(this.getLastName());
285	    }
286	
287	    private static String initial(String name) {
288	        return Character.toUpperCase(name.charAt(0)) + ".";
289	    }
290	
291	    /** Points awarded when an email address is present. */
292	    private static final int EMAIL_POINTS = 2;
293	
294	    /** Points awarded when the owner has no namesakes ({@code namesakeCount} is 0). */
295	    private static final int NO_NAMESAKE_POINTS = 1;
296	
297	    /** Points awarded for belonging to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more. */
298	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
299	
300	    /** The household size at or above which {@link #LARGE_HOUSEHOLD_POINTS} are awarded. */
301	    private static final int LARGE_HOUSEHOLD_SIZE = 3;
302	
303	    /** Points awarded for qualifying tenure. */
304	    private static final int TENURE_POINTS = 3;
305	
306	    /** The tenure, in days, that must be exceeded to earn {@link #TENURE_POINTS}. */
307	    private static final long MEMBERSHIP_TENURE_THRESHOLD_DAYS = 365;
308	
309	    /**
310	     * Return this owner's membership points, starting at 0: add {@value #EMAIL_POINTS} when an email
311	     * address is present; add {@value #NO_NAMESAKE_POINTS} when the owner has no namesakes
312	     * ({@code namesakeCount} is 0); add {@value #LARGE_HOUSEHOLD_POINTS} for a household of
313	     * {@value #LARGE_HOUSEHOLD_SIZE} or more; add {@value #TENURE_POINTS} for qualifying tenure
314	     * (more than {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days since registration).
315	     */
316	    @Transient
317	    public Integer getMembershipPoints() {
318	        int points = 0;
319	        if (hasEmail()) {
320	            points += EMAIL_POINTS;
321	        }
322	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
323	            points += NO_NAMESAKE_POINTS;
324	        }
325	        if (hasLargeHousehold()) {
326	            points += LARGE_HOUSEHOLD_POINTS;
327	        }
328	        if (hasQualifyingTenure()) {
329	            points += TENURE_POINTS;
330	        }
331	        return points;
332	    }
333	
334	    /**
335	     * Return this owner's membership level, derived from {@link #getMembershipPoints() membership
336	     * points}: 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
337	     */
338	    @Transient
339	    public Integer getMembershipLevel() {
340	        int points = getMembershipPoints();
341	        if (points <= 1) {
342	            return 1;
343	        }
344	        if (points <= 3) {
345	            return 2;
346	        }
347	        if (points <= 5) {
348	            return 3;
349	        }
350	        return 4;
351	    }
352	
353	    /**
354	     * Whether this owner belongs to a household of {@value #LARGE_HOUSEHOLD_SIZE} or more, per the
355	     * {@code householdSize} captured at creation. Owners without a recorded household size do not
356	     * qualify.
357	     */
358	    private boolean hasLargeHousehold() {
359	        return this.householdSize != null && this.householdSize >= LARGE_HOUSEHOLD_SIZE;
360	    }
361	
362	    /**
363	     * Whether this owner's tenure exceeds {@value #MEMBERSHIP_TENURE_THRESHOLD_DAYS} days, i.e.
364	     * more than that many days have elapsed since the {@code registrationDate}. Owners without a
365	     * registration date have no measurable tenure and do not qualify.
366	     */
367	    private boolean hasQualifyingTenure() {
368	        if (this.registrationDate == null) {
369	            return false;
370	        }
371	        long tenureDays = ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now());
372	        return tenureDays > MEMBERSHIP_TENURE_THRESHOLD_DAYS;
373	    }
374	
375	    /** Whether this owner has a usable email address (present and not blank). */
376	    private boolean hasEmail() {
377	        return this.email != null && !this.email.isBlank();
378	    }
379	
380	    /**
381	     * Return this owner's preferred contact channel: {@code "EMAIL"} when an email address is
382	     * present, otherwise {@code "PHONE"}.
383	     */
384	    @Transient
385	    public String getContactPreference() {
386	        return hasEmail() ? "EMAIL" : "PHONE";
387	    }
388	
389	    /**
390	     * Return this owner's age band derived from the {@code birthDate} as of the
391	     * {@code registrationDate}, or {@code null} when no birth date is known.
392	     */
393	    @Transient
394	    public AgeBand getAgeBand() {
395	        if (this.birthDate == null || this.registrationDate == null) {
396	            return null;
397	        }
398	        return AgeBand.asOf(this.birthDate, this.registrationDate);
399	    }
400	
401	    /**
402	     * Return this owner's locality: the region segment of the {@code customerCode} (the leading
403	     * {@code <REGION>} of {@code <REGION>-<HASH8>}), which is fixed at creation from the postcode
404	     * (preferred, matched against the known region ranges) falling back to the city-to-region table,
405	     * or {@code "UNKNOWN"} when neither yields a region. Before the customer code is assigned the
406	     * region is resolved directly from the postcode and city.
407	     */
408	    @Transient
409	    public String getLocality() {
410	        if (this.customerCode == null) {
411	            return LocalityResolver.regionFor(this.postcode, this.city);
412	        }
413	        int separator = this.customerCode.indexOf('-');
414	        return separator < 0 ? this.customerCode : this.customerCode.substring(0, separator);
415	    }
416	
417	    /**
418	     * Return this owner's timezone: the IANA timezone name for the owner's {@link #getLocality()
419	     * locality} via the fixed region-to-timezone table, or {@code null} when the locality has no
420	     * known timezone.
421	     */
422	    @Transient
423	    public String getTimezone() {
424	        return LocalityResolver.timezoneFor(getLocality());
425	    }
426	
427	    /**
428	     * Return this owner's check digit: the single Luhn check digit computed over the digits of the
429	     * {@code customerCode}.
430	     */
431	    @Transient
432	    public Integer getCheckDigit() {
433	        return this.customerCode == null ? null : LuhnCheckDigit.of(this.customerCode);
434	    }
435	
436	    /**
437	     * Return this owner's identity key, the single derived value all duplicate detection is based
438	     * on: the normalized telephone, email and household id joined with {@code '|'} as
439	     * {@code telephone + "|" + email + "|" + householdId}, with each absent component rendered as
440	     * the empty string. Two owners are duplicates only when their whole identity keys are equal;
441	     * because the telephone is part of the key, members of one household (same {@code householdId})
442	     * with different telephones have distinct keys and are not duplicates.
443	     */
444	    @Transient
445	    public String getIdentityKey() {
446	        return keyPart(this.telephone) + "|" + keyPart(this.email) + "|" + keyPart(this.householdId);
447	    }
448	
449	    private static String keyPart(String value) {
450	        return value == null ? "" : value;
451	    }
452	
453	    protected Set<Pet> getPetsInternal() {
454	        if (this.pets == null) {
455	            this.pets = new HashSet<>();
456	        }
457	        return this.pets;
458	    }
459	
460	    protected void setPetsInternal(Set<Pet> pets) {
461	        this.pets = pets;
462	    }
463	
464	    public List<Pet> getPets() {
465	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
466	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
467	        return Collections.unmodifiableList(sortedPets);
468	    }
469	
470	    public void setPets(List<Pet> pets) {
471	        this.pets = new HashSet<>(pets);
472	    }
473	
474	    public void addPet(Pet pet) {
475	        getPetsInternal().add(pet);
476	        pet.setOwner(this);
477	    }
478	
479	    /**
480	     * Return the Pet with the given name, or null if none found for this Owner.
481	     *
482	     * @param name to test
483	     * @return true if pet name is already in use
484	     */
485	    public Pet getPet(String name) {
486	        return getPet(name, false);
487	    }
488	
489	    /**
490	     * Return the Pet with the given name, or null if none found for this Owner.
491	     *
492	     * @param name to test
493	     * @return true if pet name is already in use
494	     */
495	    public Pet getPet(String name, boolean ignoreNew) {
496	        name = name.toLowerCase();
497	        for (Pet pet : getPetsInternal()) {
498	            if (!ignoreNew || !pet.isNew()) {
499	                String compName = pet.getName();
500	                compName = compName.toLowerCase();
501	                if (compName.equals(name)) {
502	                    return pet;
503	                }
504	            }
505	        }
506	        return null;
507	    }
508	
509	    public Pet getPet(Integer petId) {
510	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
511	    }
512	
513	    @Override
514	    public String toString() {
515	        return new ToStringCreator(this)
516	
517	            .append("id", this.getId())
518	            .append("new", this.isNew())
519	            .append("lastName", this.getLastName())
520	            .append("firstName", this.getFirstName())
521	            .append("address", this.address)
522	            .append("city", this.city)
523	            .append("telephone", this.telephone)
524	            .append("email", this.email)
525	            .append("registrationDate", this.registrationDate)
526	            .toString();
527	    }
528	}
